import axios from "axios";

const API_BASE_URL =
  process.env.REACT_APP_API_URL ||
  "http://127.0.0.1:8000";

const api = axios.create({
  baseURL: API_BASE_URL,
  headers: {
    Accept: "application/json",
  },
});

api.interceptors.request.use(
  (config) => {
    const token =
      localStorage.getItem("access_token");

    if (token) {
      config.headers =
        config.headers || {};

      config.headers.Authorization =
        `Bearer ${token}`;
    }

    return config;
  },

  (error) => Promise.reject(error)
);

export const getApiErrorMessage = (
  error,
  fallback = "Something went wrong."
) => {
  const detail =
    error?.response?.data?.detail;

  if (Array.isArray(detail)) {
    return detail
      .map((item) => item?.msg || String(item))
      .filter(Boolean)
      .join(", ");
  }

  if (typeof detail === "string" && detail) {
    return detail;
  }

  if (error?.response?.data?.message) {
    return error.response.data.message;
  }

  if (error?.message) {
    return error.message;
  }

  return fallback;
};


// =========================================================
// API ផ្សេងៗរបស់អ្នកទុកនៅទីនេះ
// AUTH, COURSES, GALLERY, SCHOOL...
// =========================================================


// =========================================================
// ALUMNI API
// =========================================================

export const getAllAlumni = async (
  skip = 0,
  limit = 200
) => {
  const response = await api.get(
    "/api/alumni/admin/all",
    {
      params: {
        skip,
        limit,
      },
    }
  );

  return response.data;
};


export const getFeaturedAlumni = async (
  limit = 6
) => {
  const response = await api.get(
    "/api/alumni/featured",
    {
      params: {
        limit,
      },
    }
  );

  return response.data;
};


export const getAlumniList = async (
  skip = 0,
  limit = 100
) => {
  const response = await api.get(
    "/api/alumni/",
    {
      params: {
        skip,
        limit,
      },
    }
  );

  return response.data;
};


export const getAlumni = async (
  alumniId
) => {
  const response = await api.get(
    `/api/alumni/${alumniId}`
  );

  return response.data;
};


export const createAlumni = async (
  data
) => {
  const response = await api.post(
    "/api/alumni/",
    data
  );

  return response.data;
};


export const updateAlumni = async (
  alumniId,
  data
) => {
  const response = await api.put(
    `/api/alumni/${alumniId}`,
    data
  );

  return response.data;
};


export const deleteAlumni = async (
  alumniId
) => {
  const response = await api.delete(
    `/api/alumni/${alumniId}`
  );

  return response.data;
};


export const alumniAPI = {
  getAll: getAllAlumni,
  getFeatured: getFeaturedAlumni,
  getPublic: getAlumniList,
  getOne: getAlumni,
  create: createAlumni,
  update: updateAlumni,
  delete: deleteAlumni,
};


// =========================================================
// DEFAULT EXPORT
// ត្រូវមាននៅបន្ទាត់ចុងក្រោយ
// =========================================================

export default api;
